---
import { cn } from "@/utils/cn";
import type { HTMLAttributes } from "astro/types";

export interface Props extends HTMLAttributes<"div"> {
  defaultValue?: string;
  orientation?: "horizontal" | "vertical";
  /**
   * Sync the active tab with a URL search param of this name, so the
   * selected tab survives reloads and can be shared as a link.
   */
  syncKey?: string;
}

const {
  defaultValue,
  orientation = "horizontal",
  syncKey,
  class: className,
  ...props
} = Astro.props;

const classes = cn(
  "w-full",
  orientation === "vertical" && "grid grid-cols-1 lg:grid-cols-2 gap-4",
  className
);
---

<div
  class={classes}
  data-tabs
  data-default-value={defaultValue}
  data-orientation={orientation}
  data-sync-key={syncKey}
  {...props}
>
  <slot />
</div>

<script>
  import { registerUiInit } from "@/utils/runtime/loader";
  import { initTabs } from "@/utils/runtime/tabs";

  registerUiInit(initTabs);
</script>

---
import { cn } from "@/utils/cn";
import type { HTMLAttributes } from "astro/types";

export interface Props extends HTMLAttributes<"div"> {
  value: string;
}

const { value, class: className, ...props } = Astro.props;

const classes = cn(
  "mt-2 ring-offset-background",
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
  className
);
---

<div
  role="tabpanel"
  class={classes}
  data-tabs-content
  data-value={value}
  data-state="inactive"
  tabindex="0"
  hidden
  {...props}
>
  <slot />
</div>

---
import { cn } from "@/utils/cn";
import type { HTMLAttributes } from "astro/types";

export interface Props extends HTMLAttributes<"div"> {}

const {
  class: className,
  ...props
} = Astro.props;

const classes = cn(
  // relative: anchors the sliding [data-tabs-indicator] pill the runtime adds
  "relative flex w-fit h-10 items-center justify-center rounded-lg bg-muted p-1 text-muted-foreground gap-1",
  className
);
---

<div
  role="tablist"
  class={classes}
  data-tabs-list
  {...props}
>
  <slot />
</div>

<style>
  :global([data-tabs-list][data-orientation="vertical"]) {
    display: flex;
    flex-direction: column;
    height: auto;
    width: 100%;
  }
</style>

---
import { cn } from "@/utils/cn";
import type { HTMLAttributes } from "astro/types";

export interface Props extends HTMLAttributes<"button"> {
  value: string;
}

const { value, class: className, ...props } = Astro.props;

const classes = cn(
  // relative: keeps the label above the sliding indicator pill behind it
  "relative inline-flex items-center justify-center whitespace-nowrap rounded-md px-3 py-1.5",
  "text-sm font-medium text-muted-foreground ring-offset-background transition-all",
  "hover:text-foreground",
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
  "disabled:pointer-events-none disabled:opacity-50",
  "data-[state=active]:text-foreground",
  className
);
---

<button
  type="button"
  role="tab"
  class={classes}
  data-tabs-trigger
  data-value={value}
  data-state="inactive"
  aria-selected="false"
  tabindex="-1"
  {...props}
>
  <slot />
</button>

<style>
  :global([data-tabs-trigger][data-orientation="vertical"]) {
    width: 100%;
    justify-content: flex-start;
  }
</style>
